const $=id=>document.getElementById(id);
const map=q=>"https://www.google.com/maps/search/"+encodeURIComponent(q+" Tamil Nadu");
const P=[["Madurai","Meenakshi Amman Temple","14 towering gopurams, thousand-pillar hall and Dravidian art.","🛕"],
["Thanjavur","Brihadeeswarar Temple","UNESCO Great Living Chola Temple built by Rajaraja I.","🏛️"],
["The Nilgiris","Ooty","Queen of Hill Stations: tea estates, gardens and toy train.","⛰️"],
["Chennai","Marina Beach","13 km urban beach along the Bay of Bengal.","🏖️"]];
const H=[["Coimbatore","Valparai","Anaimalai hills, 40 hairpin bends, tea gardens and macaques.","🌿"],
["Salem","Yercaud","Jewel of the Shevaroys: lakes, coffee and viewpoints.","☕"]];
const F=[["Breakfast Classic","Idli & Medu Vada","Soft rice cakes and crispy lentil vadas with sambar and chutneys.","🍚"],
["Golden Crepe","Ghee Roast Dosa","Crispy fermented crepe roasted in pure ghee.","🥞"],
["Grand Feast","Banana Leaf Meals","Rice, sambar, rasam, kootu, poriyal and buttermilk on a plantain leaf.","🍃"],
["Spicy Heritage","Chettinad Pepper Chicken","Hand-roasted pepper, shallots, curry leaves and kalpasi.","🍗"],
["Royal Dum","Dindigul Seeraga Samba Biryani","Fragrant small-grain dum biryani with brinjal dalcha.","🍛"],
["Street Legend","Madurai Bun Parotta & Salna","Flaky layered parotta with spicy gravy.","🫓"],
["Kaapi Culture","Kumbakonam Degree Coffee","Frothy chicory filter coffee in a brass dabara.","☕"],
["Cooler","Madurai Jigarthanda","Cold milk, almond gum, ice cream and sarsaparilla syrup.","🥤"]];
const D="Ariyalur|Gangaikonda Cholapuram,Chengalpattu|Mahabalipuram Shore Temple,Chennai|Marina Beach,Coimbatore|Marudhamalai Temple,Cuddalore|Pichavaram Mangroves,Dharmapuri|Hogenakkal Falls,Dindigul|Kodaikanal,Erode|Bannari Amman Temple,Kallakurichi|Kalrayan Hills,Kanchipuram|Kamakshi Amman Temple,Kanyakumari|Vivekananda Rock,Karur|Pasupatheeswarar Temple,Krishnagiri|Krishnagiri Dam,Madurai|Meenakshi Temple,Mayiladuthurai|Mayuranathar Temple,Nagapattinam|Velankanni Basilica,Namakkal|Namakkal Fort,Nilgiris|Ooty,Perambalur|Sathanur Fossil Tree Park,Pudukkottai|Sittanavasal Caves,Ramanathapuram|Rameswaram,Ranipet|Arcot Heritage,Salem|Yercaud,Sivaganga|Chettinad Mansions,Tenkasi|Courtallam Falls,Thanjavur|Brihadeeswarar Temple,Theni|Meghamalai,Thoothukudi|Tiruchendur Murugan Temple,Tiruchirappalli|Rockfort Temple,Tirunelveli|Nellaiappar Temple,Tirupathur|Yelagiri Hills,Tiruppur|Amaravathi Dam,Tiruvallur|Pulicat Lake,Tiruvannamalai|Arunachaleswarar Temple,Tiruvarur|Thyagaraja Temple,Vellore|Vellore Fort,Viluppuram|Auroville,Virudhunagar|Srivilliputhur Andal Temple".split(",").map(s=>s.split("|"));
const card=(i,t,h,p,link,im)=>`<article class="card"><div class="img">${im?`<img src="${im}" alt="${h}" loading="lazy">`:i}</div><div class="body"><span class="tag">${t}</span><h3>${h}</h3>${p?`<p>${p}</p>`:""}${link?`<a class="map" target="_blank" rel="noopener noreferrer" href="${map(link)}">📍 View on Google Maps</a>`:""}</div></article>`;
const IM={"Madurai": "data:image/jpeg;base64,", "Chennai": "data:image/jpeg;base64,", "Thanjavur": "data:image/jpeg;base64,", "Ooty": "data:image/jpeg;base64,"};
$("pg").innerHTML=P.map((x,i)=>card(x[3],x[0],x[1],x[2],x[1],IM[["Madurai","Thanjavur","Ooty","Chennai"][i]])).join("");
const IH={"Valparai": "data:image/jpeg;base64,", "Yercaud": "data:image/jpeg;base64,"};
$("hg").innerHTML=H.map(x=>card(x[3],x[0],x[1],x[2],x[1],IH[x[1]])).join("");
const IF=["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"];
$("fg").innerHTML=F.map((x,i)=>card(x[3],x[0],x[1],x[2],null,IF[i])).join("");
const ID=["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"];
const ID2=["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"];
const ID3=["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"];
const ID4=["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"];
const ID5=["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"];
const ID6=["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"];
const ID7=["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"];
$("dg").innerHTML=D.map((x,i)=>card("📍","#"+String(i+1).padStart(2,"0"),x[0],x[1],x[0]+" "+x[1],ID.concat(ID2,ID3,ID4,ID5,ID6,ID7)[i])).join("");
function filt(inp,sel,none){$(inp).addEventListener("input",function(){const q=this.value.toLowerCase().trim();let c=0;document.querySelectorAll(sel).forEach(el=>{const ok=el.textContent.toLowerCase().includes(q);el.style.display=ok?"":"none";if(ok)c++});$(none).style.display=c?"none":"block"})}
filt("ps","#pg .card","pn");filt("ds","#dg .card","dn");
const root=document.documentElement,tb=$("theme");
function setT(t){root.setAttribute("data-theme",t);tb.textContent=t==="dark"?"☀️":"🌙";try{localStorage.setItem("tn_theme",t)}catch(e){}}
let s=null;try{s=localStorage.getItem("tn_theme")}catch(e){}
if(s)setT(s);else if(matchMedia("(prefers-color-scheme: dark)").matches)setT("dark");
tb.onclick=()=>setT(root.getAttribute("data-theme")==="dark"?"light":"dark");
$("y").textContent=new Date().getFullYear();
$("cf").addEventListener("submit",ev=>{ev.preventDefault();
try{const l=JSON.parse(localStorage.getItem("tn_contacts")||"[]");l.push({n:$("n").value,e:$("e").value,m:$("m").value,t:Date.now()});localStorage.setItem("tn_contacts",JSON.stringify(l))}catch(e){}
$("st").textContent="✅ Thank you, "+$("n").value+"! Your feedback was recorded.";ev.target.reset()});